    The input should also be a valid percent-encoded sequence (the output of
    qt_urlRecode is always valid).

    If \a forLocalFile is true, the result is meant to be used as a local file
    path, so this function refuses to produce anything that would not be safe
    for that use. Percent-encoded sequences from %80 to %FF must then form
    valid UTF-8 and are decoded as such, instead of being replaced with
    QChar::ReplacementCharacter. This function returns -1 if any of the
    percent-encoded sequences decodes to:

    \list
      \li a NUL character;
      \li a slash ('/');
      \li a backslash ('\\'), on Windows only;
      \li a byte from %80 to %FF that is not part of a valid UTF-8 sequence.
    \endlist

    In that case, \a appendTo is restored to the contents it had on entry,
    except that it is set to a null QString if it was empty.
*/
static qsizetype decode(QString &appendTo, QStringView in, bool forLocalFile)
{
    const char16_t *begin = in.utf16();
    const char16_t *end = begin + in.size();

    // fast check whether there's anything to be decoded in the first place
    const char16_t *input = QtPrivate::qustrchr(in, '%');

    if (Q_LIKELY(input == end))
        return 0;           // nothing to do, it was already decoded!

    const auto isUnsafeForLocalFile = [](char16_t c) {
        return c == u'\0' || c == u'/'
#ifdef Q_OS_WIN
                || c == u'\\'
#endif
                ;
    };

    // detach
    const qsizetype origSize = appendTo.size();
    const auto refuse = [&]() -> qsizetype {
        if (origSize)
            appendTo.truncate(origSize);
        else
            appendTo = QString();
        return -1;
    };

